{"code":"from collections import deque
Q=[(41,6),(35,6),(29,6),(23,6),(17,6),(17,12),(17,18),(23,18),(29,18),(29,24),(29,30),(23,30),(17,30),(17,36),(17,42),(23,42),(29,42),(29,48),(29,54),(23,54),(17,54)]
T=[(17,6),(23,6),(29,6),(35,6),(41,6)]
C={'Q':Q,'T':T};A=[(k,d) for k in C for d in [-1,1]]
def mp(p,a):
 cy=C[a[0]]
 return cy[(cy.index(p)+a[1])%len(cy)] if p in cy else p
def ca(ps):return tuple(sorted(ps))
goal=ca([(17,6),(41,6)])
starts=[('fresh',ca([(17,18),(29,54)])),('current',ca([(23,18),(23,54)]))]
for nm,start in starts:
 q=deque([start]);prev={start:(None,None)}
 while q:
  s=q.popleft()
  if s==goal:break
  for a in A:
   ns=ca([mp(p,a) for p in s])
   if ns not in prev:prev[ns]=(s,a);q.append(ns)
 print('\n',nm,'visited',len(prev),'found',goal in prev)
 p=[];s=goal
 if s in prev:
  while prev[s][0] is not None:
   ps,a=prev[s];p.append((a,s));s=ps
  p=p[::-1];print('dist',len(p),start)
  for a,s in p:print(a,s)
 # reverse and optimal first/path
 rg={goal:0};qq=deque([goal])
 while qq:
  s=qq.popleft()
  for a in A:
   ns=ca([mp(x,a) for x in s])
   if ns not in rg:rg[ns]=rg[s]+1;qq.append(ns)
 print('D',rg.get(start),'first')
 for a in A:
  ns=ca([mp(x,a) for x in start])
  if rg.get(ns)==rg[start]-1:print(a,ns)
 paths=[]
 def rec(s,p):
  if len(paths)>=20:return
  if s==goal:paths.append(p);return
  for a in A:
   ns=ca([mp(x,a) for x in s])
   if rg.get(ns)==rg[s]-1:rec(ns,p+[a])
 rec(start,[]);print('npaths shown',len(paths));
 for p in paths[:10]:print(p)
","timeout":30}
